def load_base():
    raw=open(BASE,encoding='utf-8').read()
    dec=_json.JSONDecoder()
    k=raw.index('[')
    arr,_=dec.raw_decode(raw[k:])
    return {l['id']:l for l in arr}

def build():
    base=load_base()
    obj={}
    for v in VIS:
        L=base[v['id']]
        frames=[]
        for f in v['frames']:
            fr={'t':f['t'],'say':f['say'],'v':f['v']}
            if f.get('prop'): fr['prop']=f['prop']
            frames.append(fr)
        lesson={
          'id': v['id'], 'title': L['title'], 'ico': L['ico'], 'src': L['src'],
          'subj': L['subj'], 'mode':'steps', 'scene': v['scene'], 'comic': frames,
          'check': L['check'], 'tasks': L['tasks'],
        }
        obj[v['id']]=lesson
    lines=['window.VISKL={};']
    for lid in sorted(obj):
        lines.append('window.VISKL['+str(lid)+']='+_json.dumps(obj[lid],ensure_ascii=False)+';')
    lines.append('(function(){for(var k in window.VISKL){var id=+k;for(var i=0;i<window.ARH_LESSONS.length;i++){if(window.ARH_LESSONS[i].id===id){window.ARH_LESSONS[i]=window.VISKL[id];break;}}}})();')
    open(OUT,'w',encoding='utf-8').write('\n'.join(lines))
    print('классика-визуал:',len(obj),'->',OUT,'ids:',sorted(obj))

if __name__=='__main__':
    build()
